function.arguments:
{"script":"() => {
  const cards = document.querySelectorAll('article, [class*="card"], li[class*="recipe"]');
  const result = [];
  cards.forEach(card => {
    const a = card.querySelector('a');
    const h = card.querySelector('h1,h2,h3,h4');
    const meta = card.querySelector('[class*="meta"]');
    result.push({
      tag: card.tagName,
      classes: card.className.substring(0,80),
      title: h ? h.textContent.trim() : '',
      meta: meta ? meta.textContent.trim() : ''
    });
  });
  return result.slice(0, 20);
}"}

