{"script":"() => {
  const cards = document.querySelectorAll('a[id*="mntl-card-list-card"]');
  const results = [];
  cards.forEach(card => {
    const titleEl = card.querySelector('h2, h3, span[class*="title"]');
    let title = '';
    // Try to find the title from any nested span or heading
    const spans = card.querySelectorAll('span');
    for (const s of spans) {
      const t = s.textContent.trim();
      if (t && t.length > 5 && !t.includes('Save') && !t.includes('Ratings')) {
        title = t;
        break;
      }
    }
    results.push({ id: card.id, title });
  });
  return results;
}"}

